// Some portions generated by Co-Pilot
"use client";

import React, { useEffect, useRef, useState } from "react";
import { useLocale, useTranslations } from "next-intl";
import { Link } from "@/i18n/navigation";
import { FiArrowUpRight } from "react-icons/fi";
import { motion } from "motion/react";

interface DownloadCounterProps {
  total: number;
}

const DownloadCounter = ({ total }: DownloadCounterProps) => {
  const t = useTranslations("DownloadCounter");
  const locale = useLocale();
  const [count, setCount] = useState(0);
  const [animate, setAnimate] = useState(false);
  const counterRef = useRef<HTMLDivElement>(null);

  const endValue = total || 0;
  const startValue = Math.max(0, endValue - 10);
  const duration = 500;

  useEffect(() => {
    if (animate) return;

    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting && !animate) {
          setAnimate(true);
          let startTimestamp: number | null = null;

          const step = (timestamp: number) => {
            if (!startTimestamp) startTimestamp = timestamp;
            const progress = Math.min(
              (timestamp - startTimestamp) / duration,
              1,
            );
            setCount(
              Math.floor(progress * (endValue - startValue) + startValue),
            );
            if (progress < 1) {
              window.requestAnimationFrame(step);
            }
          };
          window.requestAnimationFrame(step);
        }
      },
      { root: null, threshold: 0.5 },
    );

    if (counterRef.current) {
      observer.observe(counterRef.current);
    }

    return () => observer.disconnect();
  }, [animate, endValue, startValue, duration]);

  return (
    <motion.div
      initial={{ opacity: 0, scale: 0.9 }}
      whileInView={{ opacity: 1, scale: 1 }}
      viewport={{ once: true }}
      transition={{ duration: 0.8 }}
      className="bg-purple py-10 sm:py-12"
      ref={counterRef}
    >
      <div className="mx-auto flex w-full max-w-7xl flex-col items-start justify-between gap-5 px-6 sm:flex-row sm:items-center sm:px-8">
        <h2 className="max-w-sm text-2xl font-medium leading-snug tracking-tight text-white">
          {t("title")}
        </h2>
        <Link
          href="/stats/download"
          className="group focus-visible:outline-2 focus-visible:outline-offset-4 focus-visible:outline-pink"
        >
          <span className="block text-4xl font-semibold tracking-tight text-[#ff78a6] sm:text-5xl">
            {count.toLocaleString(locale)}
          </span>
          <span className="mt-2 flex items-center gap-2 text-xs text-grey">
            {t("total-download-docker-pulls-ever")}
            <FiArrowUpRight aria-hidden="true" />
          </span>
        </Link>
      </div>
    </motion.div>
  );
};

export default DownloadCounter;
